/**
 * The Polygoetia importer: turns the tables of canon/polygoetia.md into canon
 * entries. It reads only what the tables state. Prose sections are not turned
 * into entries; they stay in the reference for `/canon` to quote.
 */
import { stringify } from 'yaml';
import { nameAndNote, plain, readTables, slug, splitList, type MdTable } from './markdown';

export const SOURCE_FILE = 'canon/polygoetia.md';
export const OUT_DIR = 'content/canon/polygoetia';

const HEADER =
  '# Generated by `pnpm extract` from canon/polygoetia.md. Do not edit by hand.\n' +
  '# Change it only by re-running the extractor, or in a PR labelled canon-change.\n';

type Entry = { id: string; origin: 'polygoetia'; kind: string } & Record<string, unknown>;
const entry = (id: string, kind: string, rest: Record<string, unknown>): Entry => ({
  id,
  origin: 'polygoetia',
  kind,
  ...rest,
});

const toYaml = (entries: Entry[]): string =>
  HEADER + stringify(entries, { lineWidth: 0, aliasDuplicateObjects: false });

const find = (tables: MdTable[], header: string): MdTable[] =>
  tables.filter((t) => t.headers.includes(header));

const cell = (row: Record<string, string>, key: string): string => row[key] ?? '';

/** "A label: the rest" → the label, when the cell opens with a short one. */
function leadingLabel(text: string): string | undefined {
  const m = /^([^:.;,]{3,40}):\s/.exec(text);
  return m?.[1]?.trim();
}

export interface ImportResult {
  files: Map<string, string>;
  problems: string[];
}

export function importPolygoetia(markdown: string, sha256: string): ImportResult {
  const tables = readTables(markdown);
  const problems: string[] = [];
  const regions: Entry[] = [];
  const places: Entry[] = [];
  const peoples: Entry[] = [];
  const schools: Entry[] = [];

  for (const t of find(tables, 'Island')) {
    // Heading: "The Sunward Chain (region screen 1, levels 70–84)"
    const head = nameAndNote(t.heading);
    const regionId = `pg_${slug(head.name)}`;
    const lv = /levels\s+(\d+)\D+(\d+)/.exec(head.note ?? '');
    regions.push(
      entry(regionId, 'region', {
        name: head.name,
        world: 'polygoetia',
        ...(lv ? { level_min: Number(lv[1]), level_max: Number(lv[2]) } : {}),
      }),
    );
    for (const row of t.rows) {
      const name = plain(cell(row, 'Island'));
      const id = `pg_${slug(name)}`;
      const levels = /(\d+)\D+(\d+)/.exec(cell(row, 'Levels'));
      if (!levels) problems.push(`${name}: could not read levels "${cell(row, 'Levels')}"`);
      const magic = nameAndNote(cell(row, 'Magic'));
      const hasSchool = !/^none\b/i.test(magic.name);
      const schoolId = `mag_pg_${slug(magic.name)}`;
      if (hasSchool) {
        schools.push(
          entry(schoolId, 'school', {
            name: magic.name,
            place: id,
            ...(magic.note ? { note: magic.note } : {}),
          }),
        );
      }
      const culture = cell(row, 'People and culture');
      const label = leadingLabel(culture);
      peoples.push(
        entry(`folk_${id}`, 'people', {
          ...(label ? { label } : {}),
          place: id,
          text: culture,
        }),
      );
      places.push(
        entry(id, 'place', {
          name,
          region: regionId,
          ...(levels ? { level_min: Number(levels[1]), level_max: Number(levels[2]) } : {}),
          description: culture,
          people: `folk_${id}`,
          ...(hasSchool ? { school: schoolId } : {}),
          ...(!hasSchool && magic.note ? { magic_note: magic.note } : {}),
          subs: splitList(cell(row, 'Places on it')).map((s) => {
            const sub = nameAndNote(s);
            const subName = sub.name.charAt(0).toUpperCase() + sub.name.slice(1);
            return { id: slug(sub.name), name: subName, ...(sub.note ? { note: sub.note } : {}) };
          }),
        }),
      );
    }
  }

  const placeByName = new Map(places.map((p) => [String(p.name), p.id]));
  const placeNamed = (text: string): string | undefined =>
    [...placeByName].find(([name]) => text.includes(name))?.[1];

  const groups: Entry[] = [];
  for (const t of find(tables, 'Power')) {
    for (const row of t.rows) {
      const name = plain(cell(row, 'Power'));
      const seat = placeNamed(cell(row, 'Seat'));
      if (!seat) problems.push(`Power "${name}": no island found for seat "${cell(row, 'Seat')}"`);
      groups.push(
        entry(`f_pg_${slug(name)}`, 'group', {
          name,
          world: 'polygoetia',
          ...(seat ? { seat } : {}),
          seat_text: cell(row, 'Seat'),
          ruled_by: cell(row, 'Ruled by'),
          wants: cell(row, 'Wants'),
          lever: cell(row, 'Its lever'),
        }),
      );
    }
  }

  const weathers: Entry[] = [];
  for (const t of find(tables, 'Weather')) {
    for (const row of t.rows) {
      const w = nameAndNote(cell(row, 'Weather'));
      weathers.push(
        entry(`wx_${slug(w.name)}`, 'weather', {
          name: w.name,
          ...(w.note ? { rarity: w.note } : {}),
          element: cell(row, 'Element'),
          feel: cell(row, 'Feel'),
          magic: cell(row, 'Magic'),
          life_and_work: cell(row, 'Life and work'),
        }),
      );
    }
  }

  const goods: Entry[] = [];
  for (const t of find(tables, 'What the islands have')) {
    for (const row of t.rows) {
      const name = cell(row, 'Kind');
      goods.push(
        entry(`goods_pg_${slug(name)}`, 'goods', {
          name,
          text: cell(row, 'What the islands have'),
        }),
      );
    }
  }

  const routes: Entry[] = [];
  for (const t of find(tables, 'Door')) {
    for (const row of t.rows) {
      const name = plain(cell(row, 'Door'));
      const to = placeNamed(cell(row, 'Lands at'));
      if (!to) problems.push(`Door "${name}": no island found for "${cell(row, 'Lands at')}"`);
      const fare = /(\d+)\s*pf/.exec(cell(row, 'Fare'));
      routes.push(
        entry(`route_pg_${slug(name)}`, 'route', {
          name,
          sails_from: cell(row, 'Sails from'),
          days: Number(cell(row, 'Days at sea')),
          ...(fare ? { fare_pf: Number(fare[1]) } : {}),
          ...(to ? { lands_at: to } : {}),
        }),
      );
    }
  }

  const kinds: [string, Entry[], string][] = [
    ['regions', regions, 'The two region screens'],
    ['places', places, 'Islands, with the places on them nested as `subs`'],
    ['peoples', peoples, 'One per island: its people and culture, as the reference words it'],
    ['groups', groups, 'Powers'],
    ['weathers', weathers, 'The Weathers'],
    ['schools', schools, 'Island schools, by name and island only'],
    ['goods', goods, 'Flora, fauna, food and goods, one entry per row of the table'],
    ['routes', routes, 'The two doors through the Ring'],
  ];

  const all = kinds.flatMap(([, list]) => list);
  const seen = new Set<string>();
  for (const e of all) {
    if (seen.has(e.id)) problems.push(`Duplicate id: ${e.id}`);
    seen.add(e.id);
  }

  const files = new Map<string, string>();
  for (const [file, list] of kinds) files.set(`${file}.yaml`, toYaml(list));
  files.set('REPORT.md', report(kinds, problems, sha256, markdown, { places, schools }));
  return { files, problems };
}

const NUMBER_WORDS: Record<string, number> = { twelve: 12, sixteen: 16 };

function report(
  kinds: [string, Entry[], string][],
  problems: string[],
  sha256: string,
  markdown: string,
  made: { places: Entry[]; schools: Entry[] },
): string {
  const lines = [
    '# Polygoetia import report',
    '',
    'Generated by `pnpm extract`. Do not edit by hand.',
    '',
    `- Source: \`${SOURCE_FILE}\``,
    `- Source SHA-256: \`${sha256}\``,
    '- Every entry carries `origin: polygoetia` and a `kind`. Ids are made from the names in the reference.',
    '- One entry is written for every row of the islands, powers, Weathers, goods and doors tables.',
    '- Text is kept as the reference words it. Only the first letter of a sub-place name is capitalised.',
    '- A people entry has a `label` when its island\'s text opens with one ("The Tuneri: …"). Some labels name the island\'s rule or nature, not a people.',
    '',
    '## Counts by kind',
    '',
    '| File | Entries | What |',
    '| --- | ---: | --- |',
    ...kinds.map(([file, list, about]) => `| \`${file}.yaml\` | ${list.length} | ${about} |`),
    '',
    '## Checked against the reference’s own numbers',
    '',
  ];
  const claims: [RegExp, string, number][] = [
    [/\b(\w+) (?:enchanted )?islands\b/, 'islands', made.places.length],
    [/\b(\w+) island schools\b/, 'island schools', made.schools.length],
  ];
  for (const [re, what, got] of claims) {
    const said = [...markdown.matchAll(new RegExp(re, 'g'))]
      .map((m) => NUMBER_WORDS[(m[1] ?? '').toLowerCase()])
      .find((n) => n !== undefined);
    if (said === undefined)
      lines.push(`- ${what}: the reference gives no number; ${got} imported.`);
    else {
      lines.push(
        `- ${what}: the reference says ${said}; ${got} imported${said === got ? '.' : ' (**mismatch**).'}`,
      );
    }
  }
  lines.push('', '## Could not be read', '');
  lines.push(problems.length > 0 ? problems.map((p) => `- ${p}`).join('\n') : 'Nothing.');
  lines.push(
    '',
    '## Not imported',
    '',
    'These parts of the reference are prose or notes for other content, not entries. Read them in the reference itself:',
    '',
    '- The themes table (real-world inspirations, which stay out of game text).',
    '- The Ring and what each people says of it; the hooks to plant on the mainland.',
    '- The prose on the Charter of the Four, Puruvala’s mandala, the Long Raid, the Warden of Miravel and new land.',
    '- The new disciplines and skills named in prose (Aeromancy, Hydromancy, Mentalism, Shell-Song, Weather-Lore).',
    '- The dishes list.',
    '- Schools have a name and an island only. The reference’s magic schools, faiths and open questions sections are unwritten (see `canon/README.md`), so nothing more is invented here.',
    '',
  );
  return lines.join('\n');
}
